(async () => {
  const workspace = figma.currentPage;

  const screens = {};
  workspace.children.forEach(c => {
    if (c.type === 'FRAME') {
      screens[c.name] = c;
    }
  });

  function link(sourceNode, targetScreenName) {
    if (!sourceNode || !screens[targetScreenName]) return;
    sourceNode.reactions = [{
      action: {
        type: 'NODE',
        destinationId: screens[targetScreenName].id,
        navigation: 'NAVIGATE',
        transition: null
      },
      trigger: { type: 'ON_CLICK' }
    }];
  }

  // 01_Welcome -> 02_Sign_In
  if (screens["01_Welcome"]) {
    const btn = screens["01_Welcome"].children.find(c => c.name === "Next Button");
    if (btn) link(btn, "02_Sign_In");
  }

  // 02_Sign_In -> 04_Verification
  if (screens["02_Sign_In"]) {
    const btn = screens["02_Sign_In"].children.find(c => c.name === "Next Button");
    if (btn) link(btn, "04_Verification");
  }

  // 03_Sign_Up -> 04_Verification
  if (screens["03_Sign_Up"]) {
    const btn = screens["03_Sign_Up"].children.find(c => c.name === "Next Button");
    if (btn) link(btn, "04_Verification");
  }

  // 04_Verification -> 05_Select_Store
  if (screens["04_Verification"]) {
    const btn = screens["04_Verification"].children.find(c => c.name === "Next Button");
    if (btn) link(btn, "05_Select_Store");
  }

  // 14_My_Order -> 15_Order_Payment
  if (screens["14_My_Order"] && screens["15_Order_Payment"]) {
    const tot = screens["14_My_Order"].children.find(c => c.characters && c.characters.includes("Total Price"));
    if (tot) link(tot, "15_Order_Payment");
  }

  return "Prototype links configured successfully.";
})()
